/**
 * Differential-test harness: runs a Caddy implementation against the fixtures
 * generated from the pinned build123d oracle.
 *
 *     oracleSuite("geometry", {
 *         "vector/add": expected => expectVectorClose(expected, "result", sum, EXACT_TOLERANCE),
 *     });
 *
 * The suite FAILS — never skips — when a fixture case has no implementation, an
 * implementation has no fixture case, or the fixture was generated by a version
 * other than the pinned reference. Fixtures come from
 * `reference/build123d/scripts/generate_fixtures.py` (`pnpm oracle:generate`).
 */

import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, it } from "vite-plus/test";

import type { FixtureCase } from "./fixtures.ts";

export * from "./fixtures.ts";

export type OracleImplementation = (expected: FixtureCase) => void | Promise<void>;

export interface OracleTest {
    readonly name: string;
    readonly expected: FixtureCase;
    readonly run: OracleImplementation;
}

/** What `oracleSuite` would register: one test per matched case, plus contract errors. */
export interface OracleSuitePlan {
    readonly tests: OracleTest[];
    readonly errors: string[];
}

export const FIXTURES_DIR = fileURLToPath(new URL("./fixtures/", import.meta.url));
export const EXPECTED_BUILD123D_VERSION = "0.13.0";
export const EXPECTED_OCCT_VERSION = "8.0.1";

const REGENERATE_HINT = "run `pnpm oracle:generate`";

/**
 * Pure planner behind `oracleSuite`: turns a parsed fixture document plus a set
 * of implementations into the tests to register and the contract violations to
 * report. Kept separate so the harness' own failure paths are unit-testable.
 */
export function planOracleSuite(
    fixture: unknown,
    implementations: Readonly<Record<string, OracleImplementation>>,
): OracleSuitePlan {
    let errors: string[] = [];
    let document = asRecord(fixture);
    if (document === undefined) {
        return { tests: [], errors: [`fixture is ${typeof fixture}, expected an object`] };
    }

    let suite = typeof document["suite"] === "string" ? document["suite"] : undefined;
    if (suite === undefined) {
        return { tests: [], errors: ['fixture has no "suite" name'] };
    }
    errors.push(...referenceErrors(suite, document["reference"]));

    let cases = asRecord(document["cases"]);
    if (cases === undefined) {
        errors.push(`${suite}: fixture has no "cases" object`);
        return { tests: [], errors };
    }
    if (Object.keys(cases).length === 0) {
        errors.push(`${suite}: fixture contains no cases`);
    }

    let tests: OracleTest[] = [];
    for (let name of Object.keys(cases).sort()) {
        let data = asRecord(cases[name]);
        if (data === undefined) {
            errors.push(`${suite}/${name}: case is not an object`);
            continue;
        }
        let run = Object.hasOwn(implementations, name) ? implementations[name] : undefined;
        if (run === undefined) {
            errors.push(`${suite}/${name}: fixture case has no implementation`);
            continue;
        }
        tests.push({ name, expected: { suite, name, path: "", data }, run });
    }

    for (let name of Object.keys(implementations).sort()) {
        if (!Object.hasOwn(cases, name)) {
            errors.push(
                `${suite}/${name}: implementation has no fixture case (${REGENERATE_HINT})`,
            );
        }
    }

    return { tests, errors };
}

/** Register a Vitest suite comparing `implementations` against `fixtures/<suite>.json`. */
export function oracleSuite(
    suite: string,
    implementations: Readonly<Record<string, OracleImplementation>>,
): void {
    describe(`build123d oracle: ${suite}`, () => {
        let plan: OracleSuitePlan;
        try {
            plan = planOracleSuite(readFixtureDocument(suite), implementations);
        } catch (error) {
            plan = { tests: [], errors: [error instanceof Error ? error.message : String(error)] };
        }

        for (let message of plan.errors) {
            it(`oracle contract: ${message}`, () => {
                throw new Error(message);
            });
        }
        for (let test of plan.tests) {
            it(test.name, () => test.run(test.expected));
        }
    });
}

/** Parsed `fixtures/<suite>.json`; throws with a regeneration hint when unusable. */
export function readFixtureDocument(suite: string): unknown {
    let path = `${FIXTURES_DIR}${suite}.json`;
    let text: string;
    try {
        text = readFileSync(path, "utf8");
    } catch {
        throw new Error(
            `missing fixture reference/build123d/fixtures/${suite}.json (${REGENERATE_HINT})`,
        );
    }
    let document: unknown;
    try {
        document = JSON.parse(text);
    } catch (error) {
        throw new Error(
            `invalid JSON in reference/build123d/fixtures/${suite}.json: ${String(error)}`,
        );
    }
    let record = asRecord(document);
    if (record === undefined || record["suite"] !== suite) {
        throw new Error(
            `reference/build123d/fixtures/${suite}.json declares suite ` +
                `${JSON.stringify(record?.["suite"])}, expected ${JSON.stringify(suite)}`,
        );
    }
    return document;
}

function referenceErrors(suite: string, reference: unknown): string[] {
    let header = asRecord(reference);
    if (header === undefined) {
        return [`${suite}: fixture has no "reference" header (${REGENERATE_HINT})`];
    }
    let errors: string[] = [];
    let expected = {
        build123d: EXPECTED_BUILD123D_VERSION,
        occt: EXPECTED_OCCT_VERSION,
    };
    for (let [key, want] of Object.entries(expected)) {
        let got = header[key];
        if (got !== want) {
            errors.push(
                `${suite}: fixture was generated against ${key} ${JSON.stringify(got)}, ` +
                    `this harness pins ${JSON.stringify(want)} (${REGENERATE_HINT})`,
            );
        }
    }
    return errors;
}

function asRecord(value: unknown): Record<string, unknown> | undefined {
    if (typeof value !== "object" || value === null || Array.isArray(value)) return undefined;
    return value as Record<string, unknown>;
}
